<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\TaxProfile; use App\Models\Sale; use App\Models\Purchase; use App\Services\BranchContext; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class TaxProfileController extends Controller
{
 public function index(){return TaxProfile::where('is_active',true)->orderByDesc('is_default')->orderBy('name')->get();}
 public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:100','tax_code'=>'required|string|max:40|unique:tax_profiles,tax_code','rate'=>'required|numeric|min:0|max:100','calculation'=>'required|in:exclusive,inclusive','is_active'=>'boolean','is_default'=>'boolean']);if(!empty($d['is_default']))TaxProfile::where('is_default',true)->update(['is_default'=>false]);return response()->json(['data'=>TaxProfile::create($d)],201);}
 public function update(Request $r,TaxProfile $taxProfile){$d=$r->validate(['name'=>'sometimes|required|string|max:100','tax_code'=>'sometimes|required|string|max:40|unique:tax_profiles,tax_code,'.$taxProfile->id,'rate'=>'sometimes|required|numeric|min:0|max:100','calculation'=>'sometimes|required|in:exclusive,inclusive','is_active'=>'sometimes|boolean','is_default'=>'sometimes|boolean']);if(!empty($d['is_default']))TaxProfile::where('is_default',true)->where('id','!=',$taxProfile->id)->update(['is_default'=>false]);$taxProfile->update($d);return response()->json(['data'=>$taxProfile]);}
 public function destroy(TaxProfile $taxProfile){abort_if(Sale::where('tax_profile_id',$taxProfile->id)->exists(),422,'This tax profile is already in use. Deactivate it instead.');$taxProfile->delete();return response()->json(['message'=>'Tax profile deleted.']);}
 public function report(Request $r){$d=$r->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from']);$from=$d['from']??today()->startOfMonth()->toDateString();$to=$d['to']??today()->toDateString();$sales=Sale::where('branch_id',BranchContext::id())->whereBetween('sale_date',[$from,$to])->selectRaw('COALESCE(SUM(tax),0) tax_collected, COALESCE(SUM(total),0) sales_total')->first();$purchases=Purchase::where('branch_id',BranchContext::id())->whereBetween('purchase_date',[$from,$to])->selectRaw('COALESCE(SUM(tax),0) input_tax, COALESCE(SUM(total),0) purchase_total')->first();return response()->json(['from'=>$from,'to'=>$to,'sales_tax'=>(float)$sales->tax_collected,'purchase_tax'=>(float)$purchases->input_tax,'net_tax_payable'=>round((float)$sales->tax_collected-(float)$purchases->input_tax,2),'sales_total'=>(float)$sales->sales_total,'purchase_total'=>(float)$purchases->purchase_total]);}
}
